// ------------------------------------------------------------------ text
//
// Unicode classification and case mapping (tables in gojo_unicode.c,
// generated by scripts/gen_unicode.py), and the string and number helpers
// behind the prelude's methods on `str`, `String`, `rune` and the integer and
// float types.

static uint16_t rune_bits(int32_t r) {
    if (r < 0) return 0;
    int64_t lo = 0, hi = (int64_t)(sizeof gojo_uprops / sizeof gojo_uprops[0]) - 1;
    while (lo <= hi) {
        int64_t mid = (lo + hi) / 2;
        if ((uint32_t)r < gojo_uprops[mid].lo) hi = mid - 1;
        else if ((uint32_t)r > gojo_uprops[mid].hi) lo = mid + 1;
        else return gojo_uprops[mid].bits;
    }
    return 0;
}

static int32_t rune_map(const gojo_umap *t, int64_t n, int32_t r) {
    int64_t lo = 0, hi = n - 1;
    while (lo <= hi) {
        int64_t mid = (lo + hi) / 2;
        if (r < t[mid].lo) hi = mid - 1;
        else if (r > t[mid].hi) lo = mid + 1;
        else return (r - t[mid].lo) % t[mid].stride == 0 ? r + t[mid].delta : r;
    }
    return r;
}

#define RUNE_MAP(t, r) rune_map(t, (int64_t)(sizeof t / sizeof t[0]), r)

static inline int32_t rune_upper(int32_t r) {
    if (r < 0x80) return r >= 'a' && r <= 'z' ? r - 32 : r;
    return RUNE_MAP(gojo_uupper, r);
}
static inline int32_t rune_lower(int32_t r) {
    if (r < 0x80) return r >= 'A' && r <= 'Z' ? r + 32 : r;
    return RUNE_MAP(gojo_ulower, r);
}
static inline int32_t rune_fold(int32_t r) {
    if (r < 0x80) return r >= 'A' && r <= 'Z' ? r + 32 : r;
    return RUNE_MAP(gojo_ufold, r);
}

int64_t gojo_prelude___runeBits(int32_t r) { return rune_bits(r); }
int32_t gojo_prelude___runeUpper(int32_t r) { return rune_upper(r); }
int32_t gojo_prelude___runeLower(int32_t r) { return rune_lower(r); }

static void push_rune_any(gojo_string *s, int32_t r) {
    uint32_t c = (uint32_t)r;
    if (c < 0x80) { gojo_string_push_byte(s, (uint8_t)c); return; }
    gojo_String_pushRune(s, r);
}

// Case conversion: ASCII bytes directly, everything else rune by rune.
static gojo_string str_map_case(gojo_str s, int32_t (*f)(int32_t)) {
    gojo_string r = { NULL, 0, 0 };
    if (s.len) gojo_String_reserve(&r, s.len);
    int64_t i = 0;
    while (i < s.len) {
        uint8_t b = s.ptr[i];
        if (b < 0x80) {
            gojo_string_push_byte(&r, (uint8_t)f(b));
            i++;
            continue;
        }
        push_rune_any(&r, f(gojo_utf8_decode(s, &i)));
    }
    return r;
}

gojo_string gojo_str_toUpper(gojo_str s) { return str_map_case(s, rune_upper); }
gojo_string gojo_str_toLower(gojo_str s) { return str_map_case(s, rune_lower); }

bool gojo_str_equalFold(gojo_str a, gojo_str b) {
    int64_t i = 0, j = 0;
    while (i < a.len && j < b.len) {
        uint8_t x = a.ptr[i], y = b.ptr[j];
        if (x < 0x80 && y < 0x80) {
            if (x != y && rune_fold(x) != rune_fold(y)) return false;
            i++;
            j++;
            continue;
        }
        int32_t r = gojo_utf8_decode(a, &i), q = gojo_utf8_decode(b, &j);
        if (r != q && rune_fold(r) != rune_fold(q)) return false;
    }
    return i == a.len && j == b.len;
}

int64_t gojo_str_runeCount(gojo_str s) {
    int64_t n = 0, i = 0;
    while (i < s.len) {
        if (s.ptr[i] < 0x80) i++;
        else gojo_utf8_decode(s, &i);
        n++;
    }
    return n;
}

bool gojo_str_isAscii(gojo_str s) {
    for (int64_t i = 0; i < s.len; i++)
        if (s.ptr[i] >= 0x80) return false;
    return true;
}

bool gojo_str_isValidUtf8(gojo_str s) {
    int64_t i = 0;
    while (i < s.len) {
        uint8_t c = s.ptr[i];
        if (c < 0x80) { i++; continue; }
        int n;
        uint32_t min;
        if ((c & 0xE0) == 0xC0) { n = 2; min = 0x80; }
        else if ((c & 0xF0) == 0xE0) { n = 3; min = 0x800; }
        else if ((c & 0xF8) == 0xF0) { n = 4; min = 0x10000; }
        else return false;
        if (s.len - i < n) return false;
        uint32_t r = c & (0xFF >> (n + 1));
        for (int k = 1; k < n; k++) {
            if ((s.ptr[i + k] & 0xC0) != 0x80) return false;
            r = (r << 6) | (s.ptr[i + k] & 0x3F);
        }
        // overlong forms, surrogates and values past U+10FFFF
        if (r < min || r > 0x10FFFF || (r >= 0xD800 && r <= 0xDFFF)) return false;
        i += n;
    }
    return true;
}

int64_t gojo_prelude___decodeAt(gojo_str s, int64_t i) {
    int64_t j = i;
    int32_t r = gojo_utf8_decode(s, &j);
    return (int64_t)r << 8 | (j - i);
}

static int64_t str_find_from(gojo_str s, gojo_str sub, int64_t from) { return str_find(s, sub, from); }

int64_t gojo_prelude___strRFind(gojo_str s, gojo_str sub) {
    if (sub.len == 0) return s.len;
    if (sub.len > s.len) return -1;
    for (int64_t i = s.len - sub.len; i >= 0; i--)
        if (memcmp(s.ptr + i, sub.ptr, (size_t)sub.len) == 0) return i;
    return -1;
}

int64_t gojo_str_count(gojo_str s, gojo_str sub) {
    if (sub.len == 0) return gojo_str_runeCount(s) + 1;
    int64_t n = 0, i = 0;
    for (;;) {
        int64_t j = str_find_from(s, sub, i);
        if (j < 0) return n;
        n++;
        i = j + sub.len;
    }
}

static void vec_push_str(gojo_vec *v, gojo_str s) {
    gojo_vec_reserve(v, 1, sizeof(gojo_string));
    ((gojo_string *)v->ptr)[v->len++] = gojo_string_from(s);
}

gojo_vec gojo_str_splitN(gojo_str s, gojo_str sep, int64_t n) {
    gojo_vec v = { NULL, 0, 0 };
    if (n <= 0) return v;
    int64_t start = 0;
    while (v.len < n - 1) {
        int64_t j;
        if (sep.len == 0) {
            // between characters
            if (start >= s.len) break;
            j = start;
            gojo_utf8_decode(s, &j);
            gojo_str part = { s.ptr + start, j - start };
            vec_push_str(&v, part);
            start = j;
            continue;
        }
        j = str_find_from(s, sep, start);
        if (j < 0) break;
        gojo_str part = { s.ptr + start, j - start };
        vec_push_str(&v, part);
        start = j + sep.len;
    }
    if (sep.len == 0 && start >= s.len && v.len > 0) return v;
    gojo_str last = { s.ptr + start, s.len - start };
    vec_push_str(&v, last);
    return v;
}

static bool rune_in(gojo_str set, int32_t r) {
    int64_t i = 0;
    while (i < set.len)
        if (gojo_utf8_decode(set, &i) == r) return true;
    return false;
}

gojo_str gojo_str_trimChars(gojo_str s, gojo_str chars) {
    int64_t lo = 0;
    while (lo < s.len) {
        int64_t j = lo;
        if (!rune_in(chars, gojo_utf8_decode(s, &j))) break;
        lo = j;
    }
    int64_t hi = s.len;
    while (hi > lo) {
        // back to the start of the last character
        int64_t st = hi - 1;
        while (st > lo && (s.ptr[st] & 0xC0) == 0x80) st--;
        int64_t j = st;
        if (!rune_in(chars, gojo_utf8_decode(s, &j))) break;
        hi = st;
    }
    gojo_str r = { s.ptr + lo, hi - lo };
    return r;
}

void gojo_prelude___stringInsert(gojo_string *s, int64_t at, gojo_str t) {
    if (t.len == 0) return;
    gojo_String_reserve(s, t.len);
    memmove(s->ptr + at + t.len, s->ptr + at, (size_t)(s->len - at));
    memcpy(s->ptr + at, t.ptr, (size_t)t.len);
    s->len += t.len;
}

void gojo_prelude___stringSetLen(gojo_string *s, int64_t n) { s->len = n; }

int64_t gojo_prelude___stringPopRune(gojo_string *s) {
    if (s->len == 0) return -1;
    int64_t st = s->len - 1;
    while (st > 0 && (s->ptr[st] & 0xC0) == 0x80 && s->len - st < 4) st--;
    gojo_str v = { s->ptr, s->len };
    int64_t j = st;
    int32_t r = gojo_utf8_decode(v, &j);
    if (j != s->len) {
        // not a whole character at the end: the last byte alone
        st = s->len - 1;
        r = 0xFFFD;
    }
    s->len = st;
    return r;
}

void gojo_String_reserve(gojo_string *s, int64_t n) {
    if (n < 0) gojo_panic("reserve: negative size", "<runtime>");
    string_reserve(s, n);
}

int64_t gojo_String_cap(gojo_string *s) { return s->cap; }

// `T.parse`, `T.parseRadix`: an optional sign, then digits in `radix`, all of
// `s`; the magnitude may be at most `max` (or `max + 1` when negative and
// signed). The result goes to `out` as two's complement.
bool gojo_parse_int(gojo_str s, int64_t radix, bool is_signed, uint64_t max, uint64_t *out) {
    int64_t i = 0;
    bool neg = false;
    if (i < s.len && (s.ptr[i] == '+' || s.ptr[i] == '-')) {
        neg = s.ptr[i] == '-';
        i++;
    }
    if (i == s.len) return false;
    if (neg && !is_signed) {
        // "-0" is still 0
        for (int64_t k = i; k < s.len; k++)
            if (s.ptr[k] != '0') return false;
        *out = 0;
        return true;
    }
    uint64_t limit = neg ? max + 1 : max;
    uint64_t v = 0;
    for (; i < s.len; i++) {
        uint8_t c = s.ptr[i];
        int64_t d = c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'z' ? c - 'a' + 10 : c >= 'A' && c <= 'Z' ? c - 'A' + 10 : 99;
        if (d >= radix) return false;
        if (v > (limit - (uint64_t)d) / (uint64_t)radix) return false;
        v = v * (uint64_t)radix + (uint64_t)d;
    }
    *out = neg ? (uint64_t)0 - v : v;
    return true;
}

uint64_t gojo_prelude___f64Bits(double x) { uint64_t b; memcpy(&b, &x, 8); return b; }
double gojo_prelude___f64FromBits(uint64_t b) { double x; memcpy(&x, &b, 8); return x; }
uint32_t gojo_prelude___f32Bits(float x) { uint32_t b; memcpy(&b, &x, 4); return b; }
float gojo_prelude___f32FromBits(uint32_t b) { float x; memcpy(&x, &b, 4); return x; }

// ------------------------------------------------------------------ regex
//
// std/regex.gojo parses a pattern and compiles it to a program of 3-int
// instructions {op, x, y}; this is the Pike VM that runs it. Every thread of
// the NFA advances in lock step over the text, so matching takes time linear
// in the text whatever the pattern. Threads are kept in priority order, which
// gives leftmost-first (Perl, Go, Rust) semantics.
//
// meta: [anchored (only at offset 0), literal (the program is `prefix`),
//        hasFirst, first-byte bitmap (8 words)]
// A class at classes[x]: ASCII bitmap (4 words, final answer for r < 128),
// negated, fold, nprops, props (runeBits mask, or -mask for "lacks all"),
// nranges, then sorted disjoint [lo, hi] pairs.

enum { RX_MATCH, RX_CHAR, RX_FOLD, RX_ANY, RX_ANYNL, RX_CLASS, RX_SPLIT, RX_JMP, RX_SAVE, RX_ASSERT };
enum { RX_BOT = 1, RX_EOT = 2, RX_BOL = 4, RX_EOL = 8, RX_WORD = 16, RX_NOTWORD = 32 };

int32_t gojo_regex___fold(int32_t r) { return rune_fold(r); }
int64_t gojo_regex___bits(int32_t r) { return rune_bits(r); }

static bool rx_in_ranges(const int32_t *c, int32_t r) {
    int32_t np = c[6];
    int32_t nr = c[7 + np];
    const int32_t *rg = c + 8 + np;
    int32_t lo = 0, hi = nr;
    while (lo < hi) {
        int32_t m = (lo + hi) / 2;
        if (r < rg[2 * m]) hi = m;
        else if (r > rg[2 * m + 1]) lo = m + 1;
        else return true;
    }
    if (np) {
        uint16_t bits = rune_bits(r);
        for (int32_t k = 0; k < np; k++) {
            int32_t p = c[7 + k];
            if (p > 0 ? (bits & p) != 0 : (bits & -p) == 0) return true;
        }
    }
    return false;
}

static bool rx_class(const int32_t *c, int32_t r) {
    if (r < 128) return ((uint32_t)c[r >> 5] >> (r & 31)) & 1;
    bool in = rx_in_ranges(c, r);
    if (!in && c[5]) {
        int32_t f = rune_fold(r);
        in = f != r && rx_in_ranges(c, f);
    }
    return in != (c[4] != 0);
}

static inline bool rx_word(uint8_t b) {
    return (b >= '0' && b <= '9') || (b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z') || b == '_';
}

static int32_t rx_flags(const uint8_t *s, int64_t len, int64_t pos) {
    int32_t f = 0;
    if (pos == 0) f |= RX_BOT | RX_BOL;
    else if (s[pos - 1] == '\n') f |= RX_BOL;
    if (pos == len) f |= RX_EOT | RX_EOL;
    else if (s[pos] == '\n') f |= RX_EOL;
    bool a = pos > 0 && rx_word(s[pos - 1]), b = pos < len && rx_word(s[pos]);
    f |= a != b ? RX_WORD : RX_NOTWORD;
    return f;
}

typedef struct { int32_t pc, slot; int64_t old; } rx_entry;
typedef struct { int32_t *dense, *sparse; int64_t *caps; int32_t n; } rx_queue;

// Scratch memory per thread, one buffer per element type so reused memory
// always keeps its type: a match is a single C call that never yields, so no
// other task can use them meanwhile.
static _Thread_local struct { void *mem; size_t size; } rx_scratch[3];

static void *rx_buf(int k, size_t size) {
    if (size > rx_scratch[k].size) {
        free(rx_scratch[k].mem);
        size_t n = size < 1024 ? 1024 : size;
        // zeroed, so the sparse sets never read memory that wasn't written
        rx_scratch[k].mem = calloc(1, n);
        if (!rx_scratch[k].mem) gojo_panic("out of memory", NULL);
        rx_scratch[k].size = n;
    }
    return rx_scratch[k].mem;
}

typedef struct {
    const int32_t *code;
    int32_t nslots;
    rx_entry *stack;
} rx_vm;

// Adds the thread at `pc0` and everything it reaches without consuming text.
static void rx_add(rx_vm *vm, rx_queue *q, int32_t pc0, int64_t pos, int64_t *cap, int32_t flags) {
    const int32_t *code = vm->code;
    int32_t nslots = vm->nslots;
    rx_entry *stack = vm->stack;
    int64_t sp = 0;
    stack[sp++] = (rx_entry){ pc0, -1, 0 };
    while (sp > 0) {
        rx_entry e = stack[--sp];
        if (e.slot >= 0) { cap[e.slot] = e.old; continue; }
        int32_t pc = e.pc;
        for (;;) {
            uint32_t d = (uint32_t)q->sparse[pc];
            if (d < (uint32_t)q->n && q->dense[d] == pc) break;
            d = (uint32_t)q->n++;
            q->dense[d] = pc;
            q->sparse[pc] = (int32_t)d;
            const int32_t *in = code + 3 * pc;
            switch (in[0]) {
            case RX_JMP: pc = in[1]; continue;
            case RX_SPLIT: stack[sp++] = (rx_entry){ in[2], -1, 0 }; pc = in[1]; continue;
            case RX_SAVE:
                if (in[1] < nslots) {
                    stack[sp++] = (rx_entry){ 0, in[1], cap[in[1]] };
                    cap[in[1]] = pos;
                }
                pc++;
                continue;
            case RX_ASSERT:
                if ((flags & in[1]) != in[1]) break;
                pc++;
                continue;
            default:
                if (nslots) memcpy(q->caps + (int64_t)d * nslots, cap, (size_t)nslots * sizeof(int64_t));
                break;
            }
            break;
        }
    }
}

// The next offset at or after `pos` where a match could start, or -1.
static int64_t rx_skip(const int32_t *meta, gojo_str prefix, gojo_str text, int64_t pos) {
    if (prefix.len) return str_find(text, prefix, pos);
    if (!meta[2]) return pos;
    const uint32_t *fb = (const uint32_t *)(meta + 3);
    for (; pos < text.len; pos++) {
        uint8_t b = text.ptr[pos];
        if ((fb[b >> 5] >> (b & 31)) & 1) return pos;
    }
    return -1;
}

// Runs the program on `text` from `pos`. With nslots = 0, only says whether
// there is a match; otherwise writes the first nslots capture offsets of the
// leftmost-first match (-1 for groups that didn't take part) to `caps`.
bool gojo_regex___exec(gojo_slice code_s, gojo_slice classes_s, gojo_slice meta_s, gojo_str prefix,
                       gojo_str text, int64_t pos, int64_t nslots64, gojo_vec *caps) {
    const int32_t *code = code_s.ptr, *classes = classes_s.ptr, *meta = meta_s.ptr;
    int32_t ninst = (int32_t)(code_s.len / 3), nslots = (int32_t)nslots64;
    gojo_vec_reserve(caps, nslots, sizeof(int64_t));
    int64_t *out = caps->ptr;
    caps->len = nslots;
    for (int32_t i = 0; i < nslots; i++) out[i] = -1;
    if (pos > text.len) return false;
    bool anchored = meta[0] != 0;
    if (anchored && pos > 0) return false;
    if (meta[1]) {
        int64_t at = str_find(text, prefix, pos);
        if (at < 0 || (anchored && at != 0)) return false;
        if (nslots >= 2) { out[0] = at; out[1] = at + prefix.len; }
        return true;
    }

    size_t ncap = (size_t)ninst * (size_t)nslots;
    int32_t *ints = rx_buf(0, (size_t)ninst * 4 * sizeof(int32_t));
    int64_t *slots = rx_buf(1, (2 * ncap + (size_t)nslots) * sizeof(int64_t));
    rx_entry *stack = rx_buf(2, ((size_t)ninst * 2 + 4) * sizeof(rx_entry));
    rx_queue qs[2];
    for (int k = 0; k < 2; k++) {
        qs[k].dense = ints + (size_t)k * 2 * ninst;
        qs[k].sparse = qs[k].dense + ninst;
        qs[k].caps = slots + (size_t)k * ncap;
        qs[k].n = 0;
    }
    rx_vm vm = { code, nslots, stack };
    int64_t *fresh = slots + 2 * ncap;
    for (int32_t i = 0; i < nslots; i++) fresh[i] = -1;

    rx_queue *clist = &qs[0], *nlist = &qs[1];
    const uint8_t *s = text.ptr;
    int64_t len = text.len;
    bool matched = false;
    int32_t flags = -1;  // the assertions that hold at pos, once known
    for (;;) {
        if (!matched && (!anchored || pos == 0)) {
            if (clist->n == 0) {
                if (anchored && pos != 0) break;
                int64_t next = rx_skip(meta, prefix, text, pos);
                if (next < 0) break;
                if (next != pos) { pos = next; flags = -1; }
            }
            if (flags < 0) flags = rx_flags(s, len, pos);
            rx_add(&vm, clist, 0, pos, fresh, flags);
        }
        if (clist->n == 0) break;
        int32_t r = -1;
        int64_t w = 0;
        if (pos < len) {
            if (s[pos] < 0x80) { r = s[pos]; w = 1; }
            else { int64_t j = pos; r = gojo_utf8_decode(text, &j); w = j - pos; }
        }
        int32_t nflags = pos < len ? rx_flags(s, len, pos + w) : 0;
        nlist->n = 0;
        for (int32_t i = 0; i < clist->n; i++) {
            int32_t pc = clist->dense[i];
            const int32_t *in = code + 3 * pc;
            int64_t *cap = clist->caps + (int64_t)i * nslots;
            bool ok;
            switch (in[0]) {
            case RX_MATCH:
                matched = true;
                if (nslots == 0) return true;
                memcpy(out, cap, (size_t)nslots * sizeof(int64_t));
                goto cut;  // the lower-priority threads lose
            case RX_CHAR: ok = r == in[1]; break;
            case RX_FOLD: ok = r == in[1] || (r >= 0 && rune_fold(r) == in[1]); break;
            case RX_ANY: ok = r >= 0; break;
            case RX_ANYNL: ok = r >= 0 && r != '\n'; break;
            case RX_CLASS: ok = r >= 0 && rx_class(classes + in[1], r); break;
            default: ok = false; break;
            }
            if (ok) rx_add(&vm, nlist, pc + 1, pos + w, cap, nflags);
        }
    cut:
        if (pos >= len) break;
        rx_queue *t = clist; clist = nlist; nlist = t;
        pos += w;
        flags = nflags;
        if (matched && clist->n == 0) break;
    }
    return matched;
}
